def compute(vars):
    operating_lease_obligations = vars["v1"]
    purchase_obligations = vars["v2"]
    difference = operating_lease_obligations - purchase_obligations

    return {
        "value": difference,
        "trace": {
            "operating_lease_obligations": operating_lease_obligations,
            "purchase_obligations": purchase_obligations,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
